import {CORALS,REAGENTS,FAMILIES,VIEWS,WET_POOL,defaults,simulateWet,wetSummary} from './wetlab-engine.js';
import {specimenIcon,bottleArt,tankArt} from './wetlab-art.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,n=1)=>x==null?'—':Number(x).toFixed(n);
const colors=['#83aa9b','#cf9076','#cca467','#80abae','#ab98b7','#6b938c','#be9d91','#8b9c79'];
export function setupWetLab({modelSetup,notify,download}){
 const $=id=>document.getElementById(id);let design={groups:defaults(),seed:42,replicates:12},selected=1,data=null,summary=null,result=null,worker=null,busy=false,day=0,animation=null,tutorialTimer=null,guide=0,chosen=WET_POOL[0].id,messages=[],revision=0;
 const steps=[['先建立对照','环境对照与单独热胁迫分开。其余条件尽量保持一致，才便于讨论氮形态和共污染。'],['放入珊瑚','将左侧珊瑚拖入水槽，或先选择处理组，再点击珊瑚。三种形态是虚拟样本，不代表真实类群的敏感性排序。'],['设置暴露','点击或拖入试剂增加示意浓度，再调整温度、光照和时长。这里不提供真实试剂配制步骤。'],['培养与读数','每组设置独立水槽。每槽 3 个片段只作为子样本，画面与图表显示训练水槽的合成白化程度和光化学读数。'],['让 Agent 选模型','模型池含 8 类算法、32 个变量方案。Agent 按预算比较验证误差，并为赢家运行两种负对照。'],['解读与核查','冻结方案后才打开独立水槽测试集。导师解释模型、误差和下一项对照；模拟白化不能推出死亡或真实生态效应。']];
 $('wetlab-root').innerHTML=`<div class="wet-heading"><div><span class="eyebrow">CORAL VIRTUAL LAB / 01</span><h2>珊瑚复合胁迫 · 虚拟实验</h2><p>选择珊瑚与试剂，设置对照，再让 Agent 比较可检验的模型。</p></div><span class="wet-stamp">虚拟培养 · 全部响应为合成</span></div>
 <div class="wet-layout"><div class="wet-main"><fieldset id="wet-design"><div class="wet-workspace"><aside class="wet-shelf"><span class="wet-kicker">SPECIMENS</span><h3>珊瑚样本</h3><div class="specimen-list">${CORALS.map(c=>`<button type="button" class="specimen" draggable="true" data-coral="${c.id}" aria-label="加入${c.name}">${specimenIcon(c.id,c.color)}<span><b>${c.name}</b><small>${c.latin}</small></span></button>`).join('')}</div><button type="button" class="wet-link" id="wet-all-coral">将当前形态用于所有组</button><span class="wet-kicker">REAGENTS</span><h3>试剂架</h3><div class="reagent-list">${REAGENTS.map(r=>`<button type="button" class="reagent" draggable="true" data-reagent="${r.id}" aria-label="加入${r.name}">${bottleArt(r.color,r.formula)}<span><b>${r.name}</b><small>+${r.step} ${r.unit} / 次</small></span><i>+</i></button>`).join('')}</div><p class="wet-small">点击加入当前组，或拖入培养水槽。浓度范围仅用于虚拟实验。</p><span class="wet-kicker">INSTRUMENTS</span><div class="instrument-list"><button type="button" id="wet-inspect">放大观察</button><button type="button" id="wet-fluor">荧光读数</button></div></aside>
 <div class="wet-stage"><div class="wet-stage-top"><div><small>当前处理组</small><strong id="wet-current-group"></strong></div><span id="wet-stage-state">待培养</span></div><div id="wet-tank" class="wet-tank" tabindex="0" aria-label="珊瑚水槽，支持拖入珊瑚和试剂"></div><div id="wet-doses" class="wet-doses"></div><div class="wet-readouts"><div><small>模拟白化程度</small><b id="wet-bleach">—</b><span>水槽均值 · 非死亡率</span></div><div><small>光化学效率代理 Fv/Fm</small><b id="wet-fvfm">—</b><span>合成终点读数</span></div><div><small>培养进度</small><b id="wet-day">0 <em>天</em></b><span id="wet-coral-label">虚拟珊瑚</span></div></div><label class="wet-timeline">观察时间<input id="wet-time" type="range" min="0" max="14" step=".1" value="0" disabled></label><div class="wet-stage-actions"><button type="button" id="wet-culture" class="primary">运行虚拟培养 →</button><button type="button" id="wet-clear" class="secondary">清除本组试剂</button><button type="button" id="wet-replay" class="text-btn" disabled>重播培养过程</button></div><p class="wet-small" id="wet-action-note" role="status">已载入 6 组比较设计。你可以直接运行，也可以修改任一处理组。</p><div id="wet-inspection" class="wet-inspection hidden"></div></div></div>
 <div class="wet-groups-head"><h3>实验分组</h3><div><button type="button" id="wet-add" class="text-btn">＋ 新建组</button><button type="button" id="wet-reset" class="text-btn">恢复示例</button></div></div><div id="wet-groups" class="wet-groups"></div>
 <div class="wet-condition-panel"><div class="wet-condition-heading"><h3>当前组条件</h3><button type="button" id="wet-remove" class="text-btn">删除本组</button></div><div class="wet-conditions"><label>组名<input id="wet-name" maxlength="30"></label><label>温度 <output id="wet-temp-out"></output><input id="wet-temp" type="range" min="26" max="34" step=".5"></label><label>相对光照 <output id="wet-light-out"></output><input id="wet-light" type="range" min="20" max="180" step="10"></label><label>暴露时间（天）<input id="wet-days" type="number" min="3" max="21" step="1"></label>${REAGENTS.map(r=>`<label>${r.formula}（${r.unit}）<input id="wet-${r.id}" type="number" min="0" max="${r.max}" step="${r.step}"></label>`).join('')}<label>独立水槽 / 组<input id="wet-reps" type="number" min="8" max="30" value="12"></label><label>随机种子<input id="wet-seed" type="number" min="1" max="999999" value="42"></label></div><p class="wet-small">每个水槽含 3 个模拟片段。温度与添加浓度存在模拟测量波动；同一水槽不会跨越训练、验证和测试分区。</p></div></fieldset>
 <section class="wet-observations hidden" id="wet-observations"><div class="wet-section-title"><div><span class="wet-kicker">OBSERVATIONS</span><h3>这一轮，观察到了什么</h3></div><button id="wet-csv" class="text-btn">导出可见水槽 CSV ↓</button></div><p id="wet-sample-note" class="wet-small"></p><div class="wet-chart-grid"><div><h4>模拟白化过程</h4><div id="wet-time-chart"></div></div><div><h4>各组终点 · 均值 ± SD</h4><div id="wet-group-chart"></div></div></div><div id="wet-design-warnings" class="wet-design-warnings"></div></section>
 <section class="wet-model-section"><div class="wet-section-title"><div><span class="wet-kicker">MODEL LIBRARY / 02</span><h3>8 类算法，32 个备选方案</h3></div><select id="wet-pool-filter" aria-label="筛选算法"><option value="all">全部算法</option>${FAMILIES.map(f=>`<option value="${f.id}">${f.name}</option>`).join('')}</select></div><p class="wet-small">每类算法有热与光照、氮形态、共污染、交互项四个变量方案。每次候选拟合或负对照消耗 1 步，失败也计入预算。</p><div id="wet-pool" class="wet-pool"></div><div id="wet-model-detail" class="wet-model-detail"></div><div class="wet-model-controls"><label>规划方式<select aria-label="规划方式" id="wet-planner"><option value="llm">ModelScope Agent</option><option value="rule">固定顺序基线（无需密钥）</option></select></label><label>建模预算<select aria-label="建模预算" id="wet-budget"><option>4</option><option selected>8</option><option>12</option><option>16</option><option>24</option></select></label><button id="wet-model-run" class="primary">让 Agent 建模 →</button><button id="wet-stop" class="secondary hidden">停止</button><button id="wet-export" class="text-btn" disabled>导出实验记录 ↓</button></div><p id="wet-model-status" class="wet-feedback" role="status">先运行虚拟培养。Agent 会看到训练摘要和已完成的验证反馈。</p><div id="wet-model-results" class="hidden"></div></section></div>
 <aside class="wet-mentor"><section class="wet-guide"><div class="wet-section-title"><h3>实验讲解</h3><span id="wet-guide-count">01 / 06</span></div><div class="wet-guide-illustration">${specimenIcon('branch','#bb9370')}</div><span class="wet-kicker" id="wet-guide-tag">EXPERIMENT DESIGN</span><h4 id="wet-guide-title"></h4><p id="wet-guide-text"></p><div class="wet-guide-progress"><i id="wet-guide-progress"></i></div><div class="wet-guide-controls"><button id="wet-guide-prev" aria-label="上一步">←</button><button id="wet-guide-play">自动讲解</button><button id="wet-guide-next" aria-label="下一步">→</button></div><button id="wet-guide-ask" class="wet-link">请 Agent 讲解这一步 ↗</button></section>
 <section class="wet-chat"><div class="wet-section-title"><div class="wet-mentor-name"><svg viewBox="0 0 40 40" aria-hidden="true"><rect x="3" y="3" width="34" height="34" rx="12" fill="#dcece4"/><path d="M13 25V15l7 5 7-5v10M13 13l7-4 7 4" fill="none" stroke="#438576" stroke-width="2"/></svg><div><h3>Agent 导师</h3><small>DeepSeek / Qwen · ModelScope</small></div></div></div><p class="wet-small">使用页面上方已验证的模型连接。发送问题会消耗模型额度；每次仅发送可见实验摘要。</p><div id="wet-chat-log" class="wet-chat-log" aria-live="polite"><div class="wet-chat-note">可以问：“这组对照够不够？”“为什么选择随机森林？”“这个误差说明了什么？”</div></div><div class="wet-quick-prompts"><button data-question="检查当前实验设计，指出一个最需要补充的对照。">检查设计</button><button data-question="解释本轮实际运行的模型、变量与误差，给出下一步虚拟实验。">解读结果</button></div><form id="wet-chat-form"><label class="sr-only" for="wet-chat-input">向 Agent 提问</label><textarea id="wet-chat-input" rows="2" maxlength="1200" placeholder="问一个关于当前实验的问题…"></textarea><button id="wet-chat-send" class="primary">发送</button></form><p class="wet-small">模拟白化 ≠ 真实观测 ≠ 珊瑚死亡</p></section></aside></div>`;
 function invalidate(note){revision++;messages=[];clearInterval(animation);data=null;summary=null;result=null;day=0;$('wet-observations').classList.add('hidden');$('wet-model-results').classList.add('hidden');$('wet-export').disabled=true;$('wet-replay').disabled=true;$('wet-time').disabled=true;$('wet-model-status').textContent='设计已改变，请重新运行虚拟培养。';if(note)$('wet-action-note').textContent=note;drawPool();drawDetail();}
 function readouts(){const g=design.groups[selected],s=summary?.groups[selected],fraction=Math.min(1,day/g.days),bleach=s?3+(s.mean-3)*fraction**1.5:0;$('wet-tank').innerHTML=tankArt(g,{bleach,active:day>0&&day<g.days});$('wet-current-group').textContent=g.name;$('wet-stage-state').textContent=s?'合成培养 · '+num(day)+' 天':'待培养';$('wet-bleach').textContent=s?num(bleach)+'%':'—';$('wet-fvfm').textContent=s&&day>=g.days?num(s.fvfm,3):'—';$('wet-day').innerHTML=num(day)+' <em>天</em>';$('wet-coral-label').textContent=CORALS.find(c=>c.id===g.coral).name+' · 3 个片段 / 槽';$('wet-time').max=g.days;$('wet-time').value=day;$('wet-doses').innerHTML=REAGENTS.map(r=>`<span><i style="background:${r.color}"></i>${r.formula} ${num(g[r.id])} ${r.unit}</span>`).join('');}
 function drawGroups(){$('wet-groups').innerHTML=design.groups.map((g,i)=>`<button type="button" data-group="${i}" class="wet-group ${i===selected?'selected':''}"><span class="wet-group-number">${String(i+1).padStart(2,'0')}</span><b>${esc(g.name)}</b><small>${g.temp}°C · ${g.days} 天 · ${CORALS.find(c=>c.id===g.coral).name}</small></button>`).join('');$('wet-groups').querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.group);day=summary?design.groups[selected].days:0;drawGroups();fill();readouts();});}
 function fill(){const g=design.groups[selected];for(const key of ['name','temp','light','days','nitrate','ammonium','prometryn'])$('wet-'+key).value=g[key];$('wet-temp-out').textContent=g.temp+'°C';$('wet-light-out').textContent=g.light+'%';$('wet-seed').value=design.seed;$('wet-reps').value=design.replicates;}
 function change(kind,id){if(busy)return;const g=design.groups[selected];if(kind==='coral'){g.coral=id;invalidate('已更换当前组的虚拟珊瑚形态；需要重新培养。');}else{const r=REAGENTS.find(r=>r.id===id);if(!r)return;g[id]=Math.min(r.max,Math.round((g[id]+r.step)*10)/10);invalidate(`${g.name}：${r.name}示意浓度现为 ${g[id]} ${r.unit}。`);}$('wet-tank').classList.remove('dose-flash');void $('wet-tank').offsetWidth;$('wet-tank').classList.add('dose-flash');drawGroups();fill();readouts();}
 document.querySelectorAll('[data-coral],[data-reagent]').forEach(b=>{const kind=b.dataset.coral?'coral':'reagent',id=b.dataset.coral||b.dataset.reagent;b.onclick=()=>change(kind,id);b.ondragstart=e=>{e.dataTransfer.setData('text/plain',JSON.stringify({kind,id}));e.dataTransfer.effectAllowed='copy';};});
 $('wet-tank').ondragover=e=>{if(!busy){e.preventDefault();$('wet-tank').classList.add('drop-ready');}};$('wet-tank').ondragleave=()=>$('wet-tank').classList.remove('drop-ready');$('wet-tank').ondrop=e=>{e.preventDefault();$('wet-tank').classList.remove('drop-ready');try{const d=JSON.parse(e.dataTransfer.getData('text/plain'));if(d.kind==='coral'&&CORALS.some(c=>c.id===d.id)||d.kind==='reagent'&&REAGENTS.some(r=>r.id===d.id))change(d.kind,d.id);}catch{}};
 for(const key of ['name','temp','light','days','nitrate','ammonium','prometryn'])$('wet-'+key).onchange=()=>{const input=$('wet-'+key),v=key==='name'?input.value.trim()||'未命名组':Number(input.value);if(key!=='name'&&(!input.checkValidity()||input.value==='')){notify('请使用显示范围内的数值。');fill();return;}design.groups[selected][key]=v;invalidate('处理条件已更新；重新培养后产生对应数据。');fill();drawGroups();readouts();};
 $('wet-reps').onchange=()=>{const v=Number($('wet-reps').value);if(!Number.isInteger(v)||v<8||v>30){notify('每组应为 8–30 个独立水槽。');fill();return;}design.replicates=v;invalidate();};$('wet-seed').onchange=()=>{const v=Number($('wet-seed').value);if(!Number.isInteger(v)||v<1||v>999999){notify('随机种子应为 1–999999。');fill();return;}design.seed=v;invalidate();};
 $('wet-all-coral').onclick=()=>{const c=design.groups[selected].coral;design.groups.forEach(g=>g.coral=c);invalidate('所有组使用同一虚拟珊瑚形态，减少形态与处理混杂。');drawGroups();readouts();};
 $('wet-clear').onclick=()=>{for(const r of REAGENTS)design.groups[selected][r.id]=0;invalidate('本组试剂已清除，环境条件保持当前设置。');fill();readouts();};
 $('wet-add').onclick=()=>{if(design.groups.length>=8){notify('首版支持最多 8 个处理组。');return;}design.groups.push({...design.groups[selected],name:'新增处理 '+(design.groups.length+1)});selected=design.groups.length-1;invalidate();drawGroups();fill();readouts();};
 $('wet-remove').onclick=()=>{if(design.groups.length<=3){notify('请至少保留 3 个处理组。');return;}design.groups.splice(selected,1);selected=Math.min(selected,design.groups.length-1);invalidate();drawGroups();fill();readouts();};
 $('wet-reset').onclick=()=>{design={groups:defaults(),seed:42,replicates:12};selected=1;invalidate('已恢复 6 组示例。');drawGroups();fill();readouts();};
 function inspect(type){const panel=$('wet-inspection');panel.classList.remove('hidden');const s=summary?.groups[selected];panel.innerHTML=type==='fluor'?`<b>荧光读数</b><p>${s?'本组训练水槽 Fv/Fm 合成均值为 '+num(s.fvfm,3)+'，不是仪器实测。':'培养后显示合成 Fv/Fm 终点读数。'}</p>`:`${specimenIcon(design.groups[selected].coral,'#c78c74')}<div><b>形态观察</b><p>放大的是虚拟样本插画。水槽颜色根据合成白化程度变浅，不表示死亡。</p></div>`;}
 $('wet-inspect').onclick=()=>inspect('coral');$('wet-fluor').onclick=()=>inspect('fluor');
 function replay(){if(!summary)return;clearInterval(animation);if(matchMedia('(prefers-reduced-motion: reduce)').matches){day=design.groups[selected].days;readouts();return;}day=0;animation=setInterval(()=>{day=Math.min(design.groups[selected].days,day+design.groups[selected].days/25);readouts();if(day>=design.groups[selected].days)clearInterval(animation);},100);}
 $('wet-time').oninput=()=>{clearInterval(animation);day=Number($('wet-time').value);readouts();};$('wet-replay').onclick=replay;
 $('wet-culture').onclick=()=>{try{data=simulateWet(design);revision++;messages=[];summary=wetSummary(data);result=null;$('wet-observations').classList.remove('hidden');$('wet-model-results').classList.add('hidden');$('wet-export').disabled=true;$('wet-replay').disabled=false;$('wet-time').disabled=false;$('wet-action-note').textContent=`已完成 ${data.rows.length} 个独立模拟水槽；页面观察只显示训练分区，测试分区保持封存。`;$('wet-model-status').textContent='培养数据已准备好。可让 Agent 选择方案，或运行固定顺序基线。';drawObservations();drawPool();drawDetail();replay();}catch(error){notify(error.message);}};
 function drawObservations(){const counts=summary.splitCounts;$('wet-sample-note').textContent=`共 ${data.rows.length} 个独立水槽 × 3 个片段。训练 ${counts.train} / 验证 ${counts.validation} / 封存测试 ${counts.test}；以下均值与 SD 仅来自训练水槽。`;
  let chart='<svg viewBox="0 0 400 215" role="img" aria-label="训练水槽合成白化时间曲线">';for(const y of [0,25,50,75,100])chart+=`<path d="M35 ${180-y*1.5}H384" stroke="#e1e9e3"/><text x="25" y="${184-y*1.5}" text-anchor="end" fill="#78938b" font-size="9">${y}</text>`;const maxDay=Math.max(...design.groups.map(g=>g.days));summary.groups.forEach((g,i)=>{chart+=`<path d="${g.time.map((t,j)=>(j?'L':'M')+(35+t.day/maxDay*349)+','+(180-t.bleaching*1.5)).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.5"/>`;});chart+=`<text x="35" y="202" fill="#78938b" font-size="9">0 天</text><text x="355" y="202" fill="#78938b" font-size="9">${maxDay} 天</text></svg>`;$('wet-time-chart').innerHTML=chart;
  $('wet-group-chart').innerHTML=summary.groups.map((g,i)=>`<div class="wet-bar"><span>${esc(g.name)}<small>n=${g.n} 个水槽</small></span><div><i style="width:${g.mean}%;background:${colors[i]}"></i></div><b>${num(g.mean)} ± ${num(g.sd)}</b></div>`).join('');$('wet-design-warnings').replaceChildren(...data.warnings.map(w=>{const p=document.createElement('p');p.textContent=w;return p;}));
 }
 function drawPool(){const filter=$('wet-pool-filter').value;$('wet-pool').innerHTML=WET_POOL.filter(m=>filter==='all'||m.family===filter).map(m=>{const r=result?.models?.find(r=>r.id===m.id);return `<button data-model="${m.id}" class="wet-model-card ${m.id===chosen?'selected':''}"><img src="illustrations/${m.id}.svg" width="166" height="112" alt="${esc(m.name)}的独立方案图标"><span>${String(m.index).padStart(2,'0')} / ${FAMILIES.find(f=>f.id===m.family).short}</span><b>${esc(FAMILIES.find(f=>f.id===m.family).name)}</b><small>${VIEWS.find(v=>v.id===m.view).name}</small><em>${r?.validation?'验证 RMSE '+num(r.validation.rmse):r?.status==='unavailable'?'本轮不可用':'可选方案'}</em></button>`;}).join('');$('wet-pool').querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{chosen=b.dataset.model;drawPool();drawDetail();});}
 function drawDetail(){const m=WET_POOL.find(m=>m.id===chosen),f=FAMILIES.find(f=>f.id===m.family),v=VIEWS.find(v=>v.id===m.view),r=result?.models?.find(r=>r.id===chosen);$('wet-model-detail').innerHTML=`<img src="illustrations/${m.id}.svg" alt="" width="100"><div><b>${esc(m.name)}</b><p>${f.note} 输入：${v.note}。</p><small>${r?.validation?'本轮验证 RMSE '+num(r.validation.rmse)+' 百分点；MAE '+num(r.validation.mae)+'。'+(result.final?.winner.id===chosen?'已冻结为最终方案。':'只参与验证比较。'):r?.reason?esc(r.reason):'本轮尚未拟合；图标不代表性能优劣。'}</small></div>${r?.validation?'<button class="text-btn" id="wet-explain-model">请导师解读 ↗</button>':''}`;if($('wet-explain-model'))$('wet-explain-model').onclick=()=>ask('解释 '+m.name+' 在本轮的实际结果、输入变量、算法限制及与其他已运行方案的区别。');}
 $('wet-pool-filter').onchange=drawPool;
 function lock(value){busy=value;$('wet-design').disabled=value;$('wet-model-run').disabled=value;$('wet-budget').disabled=value;$('wet-planner').disabled=value;$('run').disabled=value;modelSetup.lock(value);$('wet-stop').classList.toggle('hidden',!value);}
 function finish(){worker?.terminate();worker=null;lock(false);}
 $('wet-model-run').onclick=async()=>{if(!data){notify('先运行虚拟培养，生成本轮实验数据。');return;}let connection=null;const budget=Number($('wet-budget').value),mode=$('wet-planner').value;try{if(mode==='llm')connection=await modelSetup.prepare(budget,'wet');}catch(error){$('wet-model-status').textContent=error.message;notify(error.message);return;}
  clearInterval(animation);revision++;messages=[];lock(true);result=null;drawPool();drawDetail();$('wet-model-results').classList.add('hidden');$('wet-export').disabled=true;$('wet-model-status').textContent=mode==='llm'?'Agent 正在阅读实验设计与训练摘要…':'正在运行明确标注的固定顺序基线…';
  worker=new Worker('wetlab-worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.progress){const p=e.data.progress;$('wet-model-status').textContent=`${mode==='llm'?'Agent':'基线'} 第 ${p.step} 轮 · 已用拟合 ${p.used}/${p.budget}`;return;}if(e.data.error){$('wet-model-status').textContent=e.data.error;finish();return;}result=e.data.result;result.design=structuredClone(design);result.dataKind='synthetic_virtual_wetlab';result.model=connection?.model||null;$('wet-model-status').textContent=result.status==='completed'?`本轮完成：${result.models.length} 个候选，合计 ${result.used}/${result.budget} 次拟合（含负对照）。${mode==='rule'?'运行的是固定顺序基线。':'由 ModelScope 大模型逐步选择。'}`:'本轮未完成冻结：'+result.status+'。测试集仍未开启。';drawResults();drawPool();drawDetail();$('wet-export').disabled=false;finish();if(mode==='llm'&&result.final)ask('用本轮已计算的数据解读最终模型、验证与测试差异、两种负对照，并指出下一项虚拟实验。');};worker.onerror=()=>{$('wet-model-status').textContent='建模模块未能运行，请刷新页面。';finish();};worker.postMessage({design:structuredClone(design),budget,mode,connection});};
 $('wet-stop').onclick=()=>{finish();$('wet-model-status').textContent='本轮已停止；已发出的请求可能仍计入平台用量。';};$('wet-planner').onchange=()=>$('wet-model-run').textContent=$('wet-planner').value==='llm'?'让 Agent 建模 →':'运行固定顺序基线 →';
 function drawResults(){const f=result.final;$('wet-model-results').classList.remove('hidden');const metrics=f?`<div class="wet-result-metrics"><div><small>冻结方案</small><b>${esc(f.winner.name)}</b></div><div><small>独立水槽测试 RMSE</small><strong>${num(f.test.rmse)} <em>百分点</em></strong></div><div><small>训练均值基线 RMSE</small><strong>${num(f.baseline.rmse)} <em>百分点</em></strong></div></div>`:'<p>未冻结，不能展示测试结果。下面保留本轮反馈。</p>';
  const rows=result.models.map(r=>`<tr><td>${esc(r.name)}</td><td>${num(r.validation?.rmse)}</td><td>${num(r.validation?.mae)}</td><td>${num(r.validation?.r2,3)}</td><td>${r.status==='evaluated'?'已拟合':esc(r.reason)}</td></tr>`).join('');
  let scatter='';if(f){scatter='<svg viewBox="0 0 300 230" role="img" aria-label="冻结模型的独立水槽测试预测与模拟观测散点图"><path d="M36 20V195H265" fill="none" stroke="#becfc4"/><path d="M36 195L251 20" stroke="#c1cebd" stroke-dasharray="4 4"/>';scatter+=f.predictions.map(p=>`<circle cx="${36+p.observed*2.15}" cy="${195-p.predicted*1.75}" r="3.5" fill="#6c9f8b" opacity=".7"/>`).join('');scatter+='<text x="93" y="221" fill="#6f8b7e" font-size="10">模拟观测白化程度（%）</text><text x="38" y="14" fill="#6f8b7e" font-size="10">预测值（%） · 独立测试水槽</text></svg>';}
  $('wet-model-results').innerHTML=metrics+`<div class="table-scroll"><table><thead><tr><th>实际运行方案</th><th>验证 RMSE ↓</th><th>验证 MAE ↓</th><th>验证 R²</th><th>状态</th></tr></thead><tbody>${rows}</tbody></table></div>`+(f?`<div class="wet-chart-grid"><div>${scatter}</div><div class="wet-controls-result"><h4>冻结赢家的负对照</h4>${f.controls.map(c=>`<p>${c.kind==='drop-chemistry'?'移除化学变量':'训练标签置乱'}<b>测试 RMSE ${num(c.metrics.rmse)}</b>${c.note?`<small>${esc(c.note)}</small>`:''}</p>`).join('')}<small>${esc(f.boundary)}</small></div></div>`:'')+`<details class="wet-audit"><summary>查看 Agent 选择理由与工具记录</summary><pre id="wet-audit-text"></pre></details>`;$('wet-audit-text').textContent=result.audit.map(a=>`第 ${a.step} 轮 · ${a.tool||a.status}\n${a.rationale||a.error||''}\n${JSON.stringify(a.result||{},null,2)}`).join('\n\n');
 }
 $('wet-export').onclick=()=>{if(result)download('CoralBleach-virtual-wetlab.json',JSON.stringify(result,null,2));};
 $('wet-csv').onclick=()=>{if(!data)return;const visible=data.rows.filter(r=>result?.final||r.split==='train');const rows=[['kind','tank_id','group','split','coral','temp_C','light_pct','days','nitrate_umol_L','ammonium_umol_L','prometryn_ug_L','bleaching_pct','fvfm'],...visible.map(r=>['synthetic',r.id,design.groups[r.group].name,r.split,r.x.coral,r.x.temp,r.x.light,r.x.days,r.x.nitrate,r.x.ammonium,r.x.prometryn,r.y,r.fvfm])];download('virtual-tanks.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');};
 function drawGuide(){$('wet-guide-count').textContent=String(guide+1).padStart(2,'0')+' / 06';$('wet-guide-title').textContent=steps[guide][0];$('wet-guide-text').textContent=steps[guide][1];$('wet-guide-progress').style.width=(guide+1)/6*100+'%';$('wet-guide-prev').disabled=guide===0;$('wet-guide-next').disabled=guide===5;}
 $('wet-guide-prev').onclick=()=>{guide=Math.max(0,guide-1);drawGuide();};$('wet-guide-next').onclick=()=>{guide=Math.min(5,guide+1);drawGuide();};$('wet-guide-play').onclick=()=>{if(tutorialTimer){clearInterval(tutorialTimer);tutorialTimer=null;$('wet-guide-play').textContent='自动讲解';return;}if(guide===5)guide=0;drawGuide();$('wet-guide-play').textContent='暂停讲解';tutorialTimer=setInterval(()=>{guide++;drawGuide();if(guide===5){clearInterval(tutorialTimer);tutorialTimer=null;$('wet-guide-play').textContent='自动讲解';}},5000);};
 function chatLine(role,text){const d=document.createElement('div');d.className='wet-message '+role;const label=document.createElement('small');label.textContent=role==='user'?'你':'Agent 导师';const p=document.createElement('p');p.textContent=text;d.append(label,p);$('wet-chat-log').append(d);d.scrollIntoView({block:'nearest',behavior:'smooth'});return p;}
 async function ask(question){if($('wet-chat-send').disabled)return;if(!question.trim())return;$('wet-chat-send').disabled=true;chatLine('user',question);const answer=chatLine('assistant','正在读取当前实验上下文…'),askedRevision=revision;try{const context={design,guide:steps[guide],training:summary,models:result?.models||[],final:result?.final||null,selected_model:chosen,recent_messages:messages.slice(-4)};const r=await modelSetup.assist(question,context);if(askedRevision!==revision){answer.textContent='实验已改变，这条回答对应旧设置，请重新提问。';return;}answer.textContent=r.text;messages.push({question,answer:r.text});messages=messages.slice(-4);}catch(error){answer.textContent='尚未获得模型回答：'+error.message;}finally{$('wet-chat-send').disabled=false;}}
 $('wet-chat-form').onsubmit=e=>{e.preventDefault();const q=$('wet-chat-input').value;$('wet-chat-input').value='';ask(q);};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));$('wet-guide-ask').onclick=()=>ask('请结合当前实验设置讲解这一步：'+steps[guide][0]+'。');
 drawGroups();fill();readouts();drawPool();drawDetail();drawGuide();
 return {busy:()=>busy};
}
